public static void solve() throws IOException {
    int n = nextInt();
    int[] l = new int[n], r = new int[n];
    Integer[] arr = new Integer[n];
    for (int i = 0; i < n; i++) {
        l[i] = nextInt();
        r[i] = nextInt();
        arr[i] = i; // store index
    }
    Arrays.sort(arr, (o1, o2) -> l[o1] - l[o2]);
    long ans = 0;
    for (int i = 0; i < n; i++) {
        int t = arr[i];
        int left = 0, right = i - 1, mid, ind = i;
        while (left <= right) {
            mid = left + (right - left) / 2;
            if (r[arr[mid]] >= l[t]) {
                ind = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        ans += (i - ind);
    }
    pw.print(ans);
}
